// VS Code Background Opacity, Grain & Image Controller
(function () {
  if (window.__vscode_bg_ctrl_initialized) return;
  window.__vscode_bg_ctrl_initialized = true;

  const GALAXY_PRESET = 'data:image/jpeg;base64,';

  let config = { opacity: 100, tint: 45, blur: 0, grain: 20, customImage: null, imageName: 'Pattern 5K' };
  try {
    const saved = localStorage.getItem('vscode_bg_settings_v2');
    if (saved) config = Object.assign({}, config, JSON.parse(saved));
  } catch (e) {}

  function applyConfig() {
    document.documentElement.style.setProperty('--bg-opacity', (config.opacity / 100).toString());
    document.documentElement.style.setProperty('--bg-overlay', (config.tint / 100).toString());
    document.documentElement.style.setProperty('--bg-blur', config.blur + 'px');
    document.documentElement.style.setProperty('--bg-grain', (config.grain / 100 * 0.45).toString());

    if (config.customImage) {
      document.documentElement.style.setProperty('--bg-custom-image', 'url("' + config.customImage + '")');
    } else {
      document.documentElement.style.removeProperty('--bg-custom-image');
    }

    try {
      localStorage.setItem('vscode_bg_settings_v2', JSON.stringify(config));
    } catch (e) {}
  }
  applyConfig();

  function findTargetContainer() {
    const containers = document.querySelectorAll('.actions-container');
    for (let i = 0; i < containers.length; i++) {
      const c = containers[i];
      if (c.querySelector('[aria-label*="Explorer"], [aria-label*="Search"], [aria-label*="Tập tin"], [aria-label*="Tìm kiếm"], .codicon-files')) {
        return c;
      }
    }
    return document.querySelector('.part.sidebar .composite-bar .actions-container') ||
           document.querySelector('.part.sidebar .monaco-action-bar .actions-container') ||
           document.querySelector('.part.activitybar .actions-container');
  }

  let panel = null;

  function createPanel() {
    if (panel) return panel;
    panel = document.createElement('div');
    panel.id = 'bg-ctrl-panel';
    panel.style.cssText = [
      'display: none',
      'position: fixed',
      'z-index: 999999',
      'width: 290px',
      'background: rgba(16, 22, 28, 0.95)',
      'backdrop-filter: blur(28px) saturate(180%)',
      '-webkit-backdrop-filter: blur(28px) saturate(180%)',
      'border: 1px solid rgba(255, 255, 255, 0.16)',
      'border-radius: 12px',
      'box-shadow: 0 16px 44px rgba(0,0,0,0.7), 0 2px 8px rgba(0,0,0,0.4)',
      'padding: 14px 16px',
      'font-family: "JetBrains Mono", -apple-system, BlinkMacSystemFont, sans-serif',
      'font-size: 12px',
      'color: #ffffff',
      'user-select: none',
      'box-sizing: border-box'
    ].join('; ');

    panel.innerHTML = `
      <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:12px; border-bottom:1px solid rgba(255,255,255,0.08); padding-bottom:8px;">
        <span style="font-weight:600; color:#59c2ff; display:flex; align-items:center; gap:6px;">
          <span class="codicon codicon-color-mode"></span> NỀN & HIỆU ỨNG
        </span>
        <span id="bg-reset-btn" style="cursor:pointer; font-size:11px; opacity:0.75; color:#9ec5e8;" title="Đặt lại mặc định">↺ Đặt lại</span>
      </div>

      <!-- Opacity Slider -->
      <div style="margin-bottom:10px;">
        <div style="display:flex; justify-content:space-between; margin-bottom:3px; font-size:11px;">
          <span style="color:#e0e6ed;">Độ rõ nền:</span>
          <span id="bg-op-val" style="color:#59c2ff; font-weight:600;">` + config.opacity + `%</span>
        </div>
        <input type="range" id="bg-op-slider" min="10" max="100" value="` + config.opacity + `" style="width:100%; height:4px; accent-color:#59c2ff; cursor:pointer;" />
      </div>

      <!-- Tint Slider -->
      <div style="margin-bottom:10px;">
        <div style="display:flex; justify-content:space-between; margin-bottom:3px; font-size:11px;">
          <span style="color:#e0e6ed;">Độ tối phủ (Tương phản):</span>
          <span id="bg-tint-val" style="color:#ffd479; font-weight:600;">` + config.tint + `%</span>
        </div>
        <input type="range" id="bg-tint-slider" min="0" max="85" value="` + config.tint + `" style="width:100%; height:4px; accent-color:#ffd479; cursor:pointer;" />
      </div>

      <!-- Blur Slider -->
      <div style="margin-bottom:10px;">
        <div style="display:flex; justify-content:space-between; margin-bottom:3px; font-size:11px;">
          <span style="color:#e0e6ed;">Độ mờ kính (Blur):</span>
          <span id="bg-blur-val" style="color:#c3e88d; font-weight:600;">` + config.blur + `px</span>
        </div>
        <input type="range" id="bg-blur-slider" min="0" max="30" value="` + config.blur + `" style="width:100%; height:4px; accent-color:#c3e88d; cursor:pointer;" />
      </div>

      <!-- Grain Slider -->
      <div style="margin-bottom:14px;">
        <div style="display:flex; justify-content:space-between; margin-bottom:3px; font-size:11px;">
          <span style="color:#e0e6ed;">Độ hạt (Film Grain):</span>
          <span id="bg-grain-val" style="color:#ff79c6; font-weight:600;">` + config.grain + `%</span>
        </div>
        <input type="range" id="bg-grain-slider" min="0" max="100" value="` + config.grain + `" style="width:100%; height:4px; accent-color:#ff79c6; cursor:pointer;" />
      </div>

      <!-- Preset Tags -->
      <div style="display:grid; grid-template-columns: 1fr 1fr; gap:5px; margin-bottom:14px;">
        <button class="bg-preset" data-op="100" data-tint="45" data-blur="0" data-grain="20" style="background:rgba(255,255,255,0.06); border:1px solid rgba(255,255,255,0.12); color:#fff; border-radius:6px; padding:4px 6px; font-size:10px; cursor:pointer;">✨ Chuẩn</button>
        <button class="bg-preset" data-op="100" data-tint="20" data-blur="0" data-grain="10" style="background:rgba(255,255,255,0.06); border:1px solid rgba(255,255,255,0.12); color:#fff; border-radius:6px; padding:4px 6px; font-size:10px; cursor:pointer;">🌟 Sáng nét</button>
        <button class="bg-preset" data-op="95" data-tint="40" data-blur="4" data-grain="45" style="background:rgba(255,255,255,0.06); border:1px solid rgba(255,255,255,0.12); color:#fff; border-radius:6px; padding:4px 6px; font-size:10px; cursor:pointer;">🎞️ Phim hạt</button>
        <button class="bg-preset" data-op="45" data-tint="30" data-blur="12" data-grain="15" style="background:rgba(255,255,255,0.06); border:1px solid rgba(255,255,255,0.12); color:#fff; border-radius:6px; padding:4px 6px; font-size:10px; cursor:pointer;">🧊 Kính mờ</button>
      </div>

      <!-- Image Switcher Section -->
      <div style="border-top:1px solid rgba(255,255,255,0.08); padding-top:10px;">
        <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:8px;">
          <span style="font-weight:600; font-size:11px; color:#59c2ff;">🖼️ HÌNH NỀN</span>
          <span id="bg-current-name" style="font-size:10px; color:#8f98a6; max-width:130px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">` + config.imageName + `</span>
        </div>

        <input type="file" id="bg-file-input" accept="image/*" style="display:none;" />
        <button id="bg-upload-btn" style="display:flex; align-items:center; justify-content:center; gap:6px; width:100%; padding:6px 10px; background:rgba(89,194,255,0.12); border:1px solid rgba(89,194,255,0.3); color:#59c2ff; border-radius:6px; font-size:11px; font-weight:500; cursor:pointer; margin-bottom:8px;">
          <span class="codicon codicon-folder"></span> Chọn ảnh từ máy tính...
        </button>

        <div style="display:flex; gap:6px;">
          <button id="bg-preset-pattern" style="flex:1; background:rgba(255,255,255,0.06); border:1px solid rgba(255,255,255,0.12); color:#fff; border-radius:6px; padding:4px 6px; font-size:10px; cursor:pointer;">🌌 Pattern 5K</button>
          <button id="bg-preset-galaxy" style="flex:1; background:rgba(255,255,255,0.06); border:1px solid rgba(255,255,255,0.12); color:#fff; border-radius:6px; padding:4px 6px; font-size:10px; cursor:pointer;">✨ Ngân hà</button>
        </div>
      </div>
    `;

    document.body.appendChild(panel);

    const opSlider = panel.querySelector('#bg-op-slider');
    const tintSlider = panel.querySelector('#bg-tint-slider');
    const blurSlider = panel.querySelector('#bg-blur-slider');
    const grainSlider = panel.querySelector('#bg-grain-slider');
    const opVal = panel.querySelector('#bg-op-val');
    const tintVal = panel.querySelector('#bg-tint-val');
    const blurVal = panel.querySelector('#bg-blur-val');
    const grainVal = panel.querySelector('#bg-grain-val');
    const currentName = panel.querySelector('#bg-current-name');

    function syncUI() {
      opSlider.value = config.opacity;
      tintSlider.value = config.tint;
      blurSlider.value = config.blur;
      grainSlider.value = config.grain;
      opVal.textContent = config.opacity + '%';
      tintVal.textContent = config.tint + '%';
      blurVal.textContent = config.blur + 'px';
      grainVal.textContent = config.grain + '%';
      currentName.textContent = config.imageName;

      const miniSlider = document.querySelector('#bg-mini-slider');
      const miniLabel = document.querySelector('#bg-mini-label');
      if (miniSlider) miniSlider.value = config.opacity;
      if (miniLabel) miniLabel.textContent = config.opacity + '%';

      applyConfig();
    }

    opSlider.addEventListener('input', function (e) {
      config.opacity = parseInt(e.target.value);
      syncUI();
    });

    tintSlider.addEventListener('input', function (e) {
      config.tint = parseInt(e.target.value);
      syncUI();
    });

    blurSlider.addEventListener('input', function (e) {
      config.blur = parseInt(e.target.value);
      syncUI();
    });

    grainSlider.addEventListener('input', function (e) {
      config.grain = parseInt(e.target.value);
      syncUI();
    });

    panel.querySelector('#bg-reset-btn').addEventListener('click', function () {
      config = { opacity: 100, tint: 45, blur: 0, grain: 20, customImage: null, imageName: 'Pattern 5K' };
      syncUI();
    });

    const presets = panel.querySelectorAll('.bg-preset');
    for (let i = 0; i < presets.length; i++) {
      presets[i].addEventListener('click', function () {
        config.opacity = parseInt(this.getAttribute('data-op'));
        config.tint = parseInt(this.getAttribute('data-tint'));
        config.blur = parseInt(this.getAttribute('data-blur'));
        config.grain = parseInt(this.getAttribute('data-grain') || 20);
        syncUI();
      });
    }

    panel.querySelector('#bg-preset-pattern').addEventListener('click', function () {
      config.customImage = null;
      config.imageName = 'Pattern 5K';
      syncUI();
    });

    panel.querySelector('#bg-preset-galaxy').addEventListener('click', function () {
      config.customImage = GALAXY_PRESET;
      config.imageName = 'Ngân hà';
      syncUI();
    });

    const fileInput = panel.querySelector('#bg-file-input');
    const uploadBtn = panel.querySelector('#bg-upload-btn');

    uploadBtn.addEventListener('click', function () {
      fileInput.click();
    });

    fileInput.addEventListener('change', function (e) {
      const file = e.target.files && e.target.files[0];
      if (!file) return;

      const reader = new FileReader();
      reader.onload = function (evt) {
        const img = new Image();
        img.onload = function () {
          const maxW = 3024;
          const maxH = 1964;
          let w = img.width;
          let h = img.height;
          if (w > maxW || h > maxH) {
            const ratio = Math.min(maxW / w, maxH / h);
            w = Math.round(w * ratio);
            h = Math.round(h * ratio);
          }
          const canvas = document.createElement('canvas');
          canvas.width = w;
          canvas.height = h;
          const ctx = canvas.getContext('2d');
          ctx.drawImage(img, 0, 0, w, h);
          const compressed = canvas.toDataURL('image/jpeg', 0.88);
          config.customImage = compressed;
          config.imageName = file.name;
          syncUI();
        };
        img.src = evt.target.result;
      };
      reader.readAsDataURL(file);
    });

    return panel;
  }

  function mountWidget() {
    if (document.getElementById('bg-ctrl-action-item')) return;
    const container = findTargetContainer();
    if (!container) return;

    createPanel();

    const li = document.createElement('li');
    li.className = 'action-item';
    li.id = 'bg-ctrl-action-item';
    li.setAttribute('role', 'presentation');
    li.style.cssText = 'display: inline-flex; align-items: center; margin-left: 6px; padding: 0 4px; height: 100%; vertical-align: middle;';

    li.innerHTML = `
      <a class="action-label codicon codicon-color-mode" id="bg-ctrl-btn" role="button" title="Tuỳ chỉnh độ mờ, độ hạt & đổi hình nền (Click để mở)" style="font-size: 15px; cursor: pointer; display: flex; align-items: center; justify-content: center; width: 24px; height: 24px; border-radius: 4px; color: #59c2ff; transition: all 0.2s;">
      </a>
      <div style="display: inline-flex; align-items: center; gap: 4px; margin-left: 2px;">
        <input type="range" id="bg-mini-slider" min="10" max="100" value="` + config.opacity + `" title="Kéo nhanh độ mờ/rõ nền" style="width: 48px; height: 3px; accent-color: #59c2ff; cursor: pointer; opacity: 0.85;" />
        <span id="bg-mini-label" style="font-size: 10px; font-family: 'JetBrains Mono', monospace; color: #59c2ff; font-weight: 500; min-width: 25px;">` + config.opacity + `%</span>
      </div>
    `;

    container.appendChild(li);

    const btn = li.querySelector('#bg-ctrl-btn');
    const miniSlider = li.querySelector('#bg-mini-slider');
    const miniLabel = li.querySelector('#bg-mini-label');

    miniSlider.addEventListener('input', function (e) {
      config.opacity = parseInt(e.target.value);
      miniLabel.textContent = config.opacity + '%';
      const opSlider = document.querySelector('#bg-op-slider');
      const opVal = document.querySelector('#bg-op-val');
      if (opSlider) opSlider.value = config.opacity;
      if (opVal) opVal.textContent = config.opacity + '%';
      applyConfig();
    });

    btn.addEventListener('click', function (e) {
      e.stopPropagation();
      const isVisible = panel.style.display === 'block';
      if (isVisible) {
        panel.style.display = 'none';
      } else {
        const rect = btn.getBoundingClientRect();
        panel.style.top = (rect.bottom + 6) + 'px';
        panel.style.left = Math.max(10, Math.min(window.innerWidth - 310, rect.left - 10)) + 'px';
        panel.style.display = 'block';
      }
    });

    document.addEventListener('click', function (e) {
      if (panel && panel.style.display === 'block' && !panel.contains(e.target) && !li.contains(e.target)) {
        panel.style.display = 'none';
      }
    });
  }

  setInterval(mountWidget, 600);
})();
